/**
 * The JavaScript write path: take one normalized catalog snapshot and produce a complete `index.db`.
 *
 * This path is two things at once, and both constrain how it may be written:
 *
 * - the **parity reference** for the native writer — fixture expectations are generated by running
 *   this code, so it must be deterministic, and it must execute {@link INDEX_SCHEMA_DDL} verbatim
 *   rather than carrying any schema shape of its own;
 * - the **degradation path** — a host without the native addon still gets a full index, at the cost of
 *   blocking the event loop for the duration (`node:sqlite` is synchronous). `IndexReport.elapsedMs`
 *   is measured here precisely so that cost can be compared against the native kernel instead of
 *   argued about.
 *
 * The file is written to `<index>.<pid>-<nonce>.tmp`, closed, and only then renamed over `index.db`.
 * The nonce keeps concurrent runs from sharing one staging file; a run that dies leaves the previous
 * index untouched, and an abandoned staging file is swept by a later run once it is an hour old.
 * @module dsh-plugin-dbgraph-store/writer-js
 */

import { mkdirSync, renameSync, rmSync } from 'node:fs'
import { dirname } from 'node:path'
import { performance } from 'node:perf_hooks'
import { DatabaseSync } from 'node:sqlite'
import {
  DbgraphError,
  INDEX_META_KEYS,
  INDEX_SCHEMA_DDL,
  INDEX_SCHEMA_VERSION,
  isValidConnectionId,
} from 'dsh-plugin-dbgraph-service'
import type {
  AliasGroup,
  ConnectionIdType,
  IndexReport,
  RawObject,
  RawCatalog,
} from 'dsh-plugin-dbgraph-service'
import { messageOf } from './message.ts'
import { normalizeComment, typeClassOf } from './normalize.ts'
import { indexPath, stagingIndexPath, sweepStaleStaging } from './paths.ts'
import { assignCatalogIds, buildTerms } from './terms.ts'

/** What one JavaScript write needs. */
export interface JsWriteInput {
  /** Connection identity; also the directory name under the root. */
  readonly connection: ConnectionIdType
  /** The snapshot to write. */
  readonly catalog: RawCatalog
  /** Alias table expanded into `terms`. */
  readonly aliases: readonly AliasGroup[]
  /** Index root (`~/.dsh/dbgraph`, or `DSH_DBGRAPH_ROOT`). */
  readonly root: string
  /** Epoch milliseconds recorded as the write time; defaults to now. */
  readonly now?: number
}

/** One relation resolved against the objects already being written. */
interface ObjectSlot {
  readonly id: number
  readonly schema: string
  readonly name: string
  readonly columns: ReadonlyMap<string, number>
  readonly columnsLower: ReadonlyMap<string, number>
}

/**
 * Execute the contract DDL and translate any failure into a structured error.
 * @param db - the staging database.
 */
function applySchema(db: DatabaseSync): void {
  for (const statement of INDEX_SCHEMA_DDL) {
    try {
      db.exec(statement)
    } catch (error) {
      /* v8 ignore start -- a DDL failure is a build-environment fault (no FTS5, no space), not an input. */
      throw new DbgraphError(
        `creating the index schema failed: ${messageOf(error)}`,
        'DBGRAPH_WRITE_FAILED',
        { cause: error },
      )
      /* v8 ignore stop */
    }
  }
}

/**
 * Index the objects being written by every lookup the edge resolver needs.
 * @param objects - the catalog objects, in write order.
 * @param objectIds - their ids.
 * @returns display-qualified and bare-name lookups.
 */
function buildObjectSlots(
  objects: readonly RawObject[],
  objectIds: readonly number[],
  columnIds: readonly (readonly number[])[],
): { byDisplay: Map<string, ObjectSlot>; byName: Map<string, ObjectSlot[]> } {
  const byDisplay = new Map<string, ObjectSlot>()
  const byName = new Map<string, ObjectSlot[]>()
  for (let index = 0; index < objects.length; index += 1) {
    const object = objects[index]
    const id = objectIds[index]
    /* v8 ignore start -- objectIds is built from the same array as objects. */
    if (object === undefined || id === undefined) continue
    /* v8 ignore stop */
    const schema = object.schema ?? ''
    const exact = new Map<string, number>()
    const lower = new Map<string, number>()
    for (let columnIndex = 0; columnIndex < object.columns.length; columnIndex += 1) {
      const column = object.columns[columnIndex]
      /* v8 ignore start -- columnIds has one id per column of this same object. */
      const columnId = (columnIds[index] ?? [])[columnIndex]
      if (column === undefined || columnId === undefined) continue
      /* v8 ignore stop */
      exact.set(column.name, columnId)
      lower.set(column.name.toLowerCase(), columnId)
    }
    const slot: ObjectSlot = { id, schema, name: object.name, columns: exact, columnsLower: lower }
    byDisplay.set(schema === '' ? object.name : `${schema}.${object.name}`, slot)
    const bucket = byName.get(object.name)
    if (bucket === undefined) byName.set(object.name, [slot])
    else bucket.push(slot)
  }
  return { byDisplay, byName }
}

/**
 * Resolve a referenced object name against the objects in this snapshot.
 * @param reference - the name the catalog reported, possibly schema-qualified.
 * @param lookups - the lookup tables from {@link buildObjectSlots}.
 * @returns the slot, or undefined when the target was not indexed.
 */
function findReferencedObject(
  reference: string,
  lookups: { byDisplay: Map<string, ObjectSlot>; byName: Map<string, ObjectSlot[]> },
): ObjectSlot | undefined {
  const direct = lookups.byDisplay.get(reference)
  if (direct !== undefined) return direct
  const bare = lookups.byName.get(reference)
  if (bare !== undefined && bare.length === 1) return bare[0]
  const lower = reference.toLowerCase()
  for (const [display, slot] of lookups.byDisplay) {
    if (display.toLowerCase() === lower) return slot
  }
  return undefined
}

/**
 * Resolve a column name inside one object.
 * @param slot - the object.
 * @param name - the declared column name.
 * @returns the column id, or undefined.
 */
function findColumnId(slot: ObjectSlot, name: string): number | undefined {
  return slot.columns.get(name) ?? slot.columnsLower.get(name.toLowerCase())
}

/**
 * Write a complete index for one connection.
 *
 * The returned counts are what was actually inserted, not what the catalog claimed, so a dropped edge
 * or a duplicate term is visible rather than assumed away.
 * @param input - the snapshot, identity, aliases and root.
 * @returns the run's report; `elapsedMs` covers schema creation, every insert, and the rename.
 */
export function writeIndexJs(input: JsWriteInput): IndexReport {
  const startedAt = performance.now()
  const connection = input.connection
  if (!isValidConnectionId(connection)) {
    throw new DbgraphError(`"${connection}" is not a usable connection id`, 'DBGRAPH_INVALID_PROVIDER')
  }
  const now = input.now ?? Date.now()
  const finalPath = indexPath(connection, input.root)
  const stagingPath = stagingIndexPath(connection, input.root)
  mkdirSync(dirname(finalPath), { recursive: true })
  // A killed run leaves its per-run staging file behind; nothing would ever reuse that name.
  sweepStaleStaging(finalPath)
  rmSync(stagingPath, { force: true })

  const catalog = input.catalog
  const ids = assignCatalogIds(catalog)
  const built = buildTerms(catalog, ids, input.aliases)
  const warnings: string[] = [...(catalog.warnings ?? [])]
  const lookups = buildObjectSlots(catalog.objects, ids.objects, ids.columns)

  let database: DatabaseSync | undefined
  let objectCount = 0
  let columnCount = 0
  let edgeCount = 0
  let skippedEdges = 0

  try {
    database = new DatabaseSync(stagingPath)
    // The staging file is disposable until the rename: there is no reader to protect and no
    // transaction to replay. The old index stays untouched, so durability buys nothing here.
    database.exec('PRAGMA journal_mode = OFF')
    database.exec('PRAGMA synchronous = OFF')
    applySchema(database)
    database.exec('BEGIN')

    const setMeta = database.prepare('INSERT OR REPLACE INTO meta (key, value) VALUES (?, ?)')
    setMeta.run(INDEX_META_KEYS.schemaVersion, String(INDEX_SCHEMA_VERSION))
    setMeta.run(INDEX_META_KEYS.connection, connection)
    setMeta.run(INDEX_META_KEYS.engine, catalog.engine)
    setMeta.run(INDEX_META_KEYS.database, catalog.database)
    if (catalog.serverVersion !== undefined) {
      setMeta.run(INDEX_META_KEYS.serverVersion, catalog.serverVersion)
    }
    setMeta.run(INDEX_META_KEYS.level, catalog.level)
    setMeta.run(INDEX_META_KEYS.fetchedAt, String(catalog.fetchedAt))
    setMeta.run(INDEX_META_KEYS.l1IndexedAt, String(catalog.fetchedAt))
    if (catalog.level === 'l2') setMeta.run(INDEX_META_KEYS.l2IndexedAt, String(catalog.fetchedAt))
    setMeta.run(INDEX_META_KEYS.writer, 'js')
    setMeta.run(INDEX_META_KEYS.writtenAt, String(now))

    const insertObject = database.prepare(
      `INSERT INTO objects (id, kind, schema_name, name, comment, row_estimate, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
    )
    const insertColumn = database.prepare(
      `INSERT INTO columns (id, object_id, ordinal, name, type, type_class, nullable, default_value,
         comment, is_primary_key, is_unique, enum_values_json, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    )

    for (let index = 0; index < catalog.objects.length; index += 1) {
      const object = catalog.objects[index]
      const objectId = ids.objects[index]
      /* v8 ignore start -- ids.objects is built from this same array. */
      if (object === undefined || objectId === undefined) continue
      /* v8 ignore stop */
      insertObject.run(
        objectId,
        object.kind,
        object.schema ?? '',
        object.name,
        normalizeComment(object.comment) ?? null,
        object.rowEstimate === undefined || !Number.isFinite(object.rowEstimate)
          ? null
          : Math.trunc(object.rowEstimate),
        now,
      )
      objectCount += 1
      /* v8 ignore start -- ids.columns has one entry per object. */
      const columnIds = ids.columns[index] ?? []
      /* v8 ignore stop */
      for (let columnIndex = 0; columnIndex < object.columns.length; columnIndex += 1) {
        const column = object.columns[columnIndex]
        const columnId = columnIds[columnIndex]
        /* v8 ignore start -- columnIds has one id per column of this same object. */
        if (column === undefined || columnId === undefined) continue
        /* v8 ignore stop */
        const enumValues = column.enumValues !== undefined && column.enumValues.length > 0
          ? JSON.stringify(column.enumValues)
          : null
        insertColumn.run(
          columnId,
          objectId,
          column.ordinal,
          column.name,
          column.type,
          typeClassOf(column.type),
          column.isPrimaryKey === true ? 0 : column.nullable === false ? 0 : 1,
          column.defaultValue ?? null,
          normalizeComment(column.comment) ?? null,
          column.isPrimaryKey === true ? 1 : 0,
          column.isUnique === true ? 1 : 0,
          enumValues,
          now,
        )
        columnCount += 1
      }
    }

    const insertEdge = database.prepare(
      `INSERT INTO edges (src_object, src_column_id, kind, dst_object, dst_column_id, name)
       VALUES (?, ?, ?, ?, ?, ?)`,
    )
    for (let index = 0; index < catalog.objects.length; index += 1) {
      const object = catalog.objects[index]
      const srcId = ids.objects[index]
      /* v8 ignore start -- ids.objects is built from this same array. */
      if (object === undefined || srcId === undefined) continue
      /* v8 ignore stop */
      const srcSlot = lookups.byDisplay.get(
        (object.schema ?? '') === '' ? object.name : `${object.schema}.${object.name}`,
      )
      for (const edge of object.edges ?? []) {
        const destination = edge.refObject === undefined ? undefined : findReferencedObject(edge.refObject, lookups)
        if (edge.refObject !== undefined && destination === undefined) {
          skippedEdges += 1
          continue
        }
        const rowCount = Math.max(1, edge.columns.length)
        for (let columnIndex = 0; columnIndex < rowCount; columnIndex += 1) {
          const sourceColumn = edge.columns[columnIndex]
          const srcColumnId = srcSlot === undefined || sourceColumn === undefined
            ? undefined
            : findColumnId(srcSlot, sourceColumn)
          if (sourceColumn !== undefined && srcColumnId === undefined) {
            skippedEdges += 1
            continue
          }
          const referencedColumn = edge.refColumns?.[columnIndex]
          const dstColumnId = destination === undefined || referencedColumn === undefined
            ? undefined
            : findColumnId(destination, referencedColumn)
          insertEdge.run(
            srcId,
            srcColumnId ?? null,
            edge.kind,
            destination?.id ?? null,
            dstColumnId ?? null,
            edge.name ?? null,
          )
          edgeCount += 1
        }
      }
    }

    const insertTerm = database.prepare('INSERT INTO terms (term, weight, object_id, column_id) VALUES (?, ?, ?, ?)')
    for (const row of built.terms) insertTerm.run(row.term, row.weight, row.objectId, row.columnId)

    const insertSearch = database.prepare('INSERT INTO search (text, object_id, column_id) VALUES (?, ?, ?)')
    for (const row of built.search) insertSearch.run(row.text, row.objectId, row.columnId)

    database.exec('COMMIT')
    database.close()
    database = undefined
    renameSync(stagingPath, finalPath)
  } catch (error) {
    try {
      database?.close()
    } catch {
      // The staging handle is already unusable; the remaining work is cleanup, not diagnosis.
    }
    rmSync(stagingPath, { force: true })
    /* v8 ignore start -- the schema guard above is the only DbgraphError path, and it is unreachable. */
    if (error instanceof DbgraphError) throw error
    /* v8 ignore stop */
    throw new DbgraphError(
      `writing the index for "${connection}" failed: ${messageOf(error)}`,
      'DBGRAPH_WRITE_FAILED',
      { cause: error },
    )
  }

  if (skippedEdges > 0) {
    warnings.push(`${skippedEdges} edge row(s) skipped: the referenced object or column is not in this snapshot`)
  }

  return {
    connection,
    level: catalog.level,
    objects: objectCount,
    columns: columnCount,
    edges: edgeCount,
    terms: built.terms.length,
    writer: 'js',
    elapsedMs: Math.round(performance.now() - startedAt),
    warnings,
  }
}
